/// `∀i ∈ [0,1]. ∃j ∈ [0,1]. a[j] = i` with `a = [0, 1]` – satisfiable.

fn test_pr30_quantified_uf_zero_divisor_pin_does_not_fabricate() {
    let output = run(r#"
        (set-logic UFLIA)
        (declare-fun f (Int) Int)
        (declare-const y Int)
        (assert (forall ((z Int)) (>= (f z) 0)))
        (assert (= y 1))
        (assert (not (= (f y) (f (div 1 0)))))
        (check-sat)
    "#);
    assert_eq!(
        output,
        vec!["sat"],
        "(div 1 0) uninterpreted: may differ from 1; z3: sat"
    );
}

/// MBQI relevant-term pool regression (ABV residual of the registry study):
/// a quantifier whose auto-trigger `(select a i)` contains no ground term of
/// the bound variable's sort left that sort's candidate pool EMPTY — ground
/// terms were collected only from patterns, defaults had no BitVec arm, and
/// injected extras replaced the strategies instead of merging — so MBQI found
/// no counterexample in any round and a refutable goal answered `unknown`
/// (z3: `unsat`).  The fix: ground sub-terms of every quantifier-free
/// assertion enter the pool; BitVec gets default candidates (exhaustive for
/// width ≤ 3, structural set above); extras MERGE into the computed lists.

fn set16_family_answers_sat() {
    let output = run_bounded(
        r#"
        (set-logic UF)
        (declare-sort Set 0)
        (declare-sort Elem 0)
        (declare-fun member (Elem Set) Bool)
        (declare-fun subset (Set Set) Bool)
        (assert (forall ((?x Elem) (?s1 Set) (?s2 Set)) (=> (and (member ?x ?s1) (subset ?s1 ?s2)) (member ?x ?s2))))
        (assert (forall ((?s1 Set) (?s2 Set)) (=> (not (subset ?s1 ?s2)) (exists ((?x Elem)) (and (member ?x ?s1) (not (member ?x ?s2)))))))
        (assert (forall ((?s1 Set) (?s2 Set)) (=> (forall ((?x Elem)) (=> (member ?x ?s1) (member ?x ?s2))) (subset ?s1 ?s2))))
        (declare-fun seteq (Set Set) Bool)
        (assert (forall ((?s1 Set) (?s2 Set)) (= (seteq ?s1 ?s2) (= ?s1 ?s2))))
        (assert (forall ((?s1 Set) (?s2 Set)) (= (seteq ?s1 ?s2) (and (subset ?s1 ?s2) (subset ?s2 ?s1)))))
        (declare-fun union (Set Set) Set)
        (assert (forall ((?x Elem) (?s1 Set) (?s2 Set)) (= (member ?x (union ?s1 ?s2)) (or (member ?x ?s1) (member ?x ?s2)))))
        (declare-fun intersection (Set Set) Set)
        (assert (forall ((?x Elem) (?s1 Set) (?s2 Set)) (= (member ?x (intersection ?s1 ?s2)) (and (member ?x ?s1) (member ?x ?s2)))))
        (declare-fun difference (Set Set) Set)
        (assert (forall ((?x Elem) (?s1 Set) (?s2 Set)) (= (member ?x (difference ?s1 ?s2)) (and (member ?x ?s1) (not (member ?x ?s2))))))
        (declare-fun a () Set)
        (declare-fun b () Set)
        (assert (= a (intersection a b)))
        (assert (not (subset b a)))
        (check-sat)
    "#,
        // The persistent-model rewrite made this an honest convergence
        // (rows no longer vanish at round boundaries): ~9 s standalone,
        // and the band needs headroom for full-suite parallel load (the
        // set9 pin's 120 s budget is the precedent).
        120_000,
    );
    let status = last_status(&output);
    assert!(
        status == "sat",
        "the constructor-table completion closes this family (z3: sat, 0.5 s); got {status}"
    );
}

/// The `set9` corpus goal, verbatim shape: the same ten axioms with
/// `not (seteq (difference a b) (difference b a))` — this needs the
/// *powerset closure* of the used rows (disjoint non-empty base rows;
/// union/intersection then demand the full and empty rows), which the
/// 2-element frozen structure lacks until the fresh-row mint grows it.
/// It also needed the structure-membership drop of entries keyed at
/// out-of-domain compounds (`union(a,b)`, `skf!0(difference(a,b),
/// difference(b,a))` — aux exploit routes the completed structure
/// never justified).  z3 answers `sat`; this is the convergence pin
/// for both mechanisms on the harder half of the family.

fn set9_family_answers_sat() {
    let output = run_bounded(
        r#"
        (set-logic UF)
        (declare-sort Set 0)
        (declare-sort Elem 0)
        (declare-fun member (Elem Set) Bool)
        (declare-fun subset (Set Set) Bool)
        (assert (forall ((?x Elem) (?s1 Set) (?s2 Set)) (=> (and (member ?x ?s1) (subset ?s1 ?s2)) (member ?x ?s2))))
        (assert (forall ((?s1 Set) (?s2 Set)) (=> (not (subset ?s1 ?s2)) (exists ((?x Elem)) (and (member ?x ?s1) (not (member ?x ?s2)))))))
        (assert (forall ((?s1 Set) (?s2 Set)) (=> (forall ((?x Elem)) (=> (member ?x ?s1) (member ?x ?s2))) (subset ?s1 ?s2))))
        (declare-fun seteq (Set Set) Bool)
        (assert (forall ((?s1 Set) (?s2 Set)) (= (seteq ?s1 ?s2) (= ?s1 ?s2))))
        (assert (forall ((?s1 Set) (?s2 Set)) (= (seteq ?s1 ?s2) (and (subset ?s1 ?s2) (subset ?s2 ?s1)))))
        (declare-fun union (Set Set) Set)
        (assert (forall ((?x Elem) (?s1 Set) (?s2 Set)) (= (member ?x (union ?s1 ?s2)) (or (member ?x ?s1) (member ?x ?s2)))))
        (declare-fun intersection (Set Set) Set)
        (assert (forall ((?x Elem) (?s1 Set) (?s2 Set)) (= (member ?x (intersection ?s1 ?s2)) (and (member ?x ?s1) (member ?x ?s2)))))
        (declare-fun difference (Set Set) Set)
        (assert (forall ((?x Elem) (?s1 Set) (?s2 Set)) (= (member ?x (difference ?s1 ?s2)) (and (member ?x ?s1) (not (member ?x ?s2))))))
        (declare-fun a () Set)
        (declare-fun b () Set)
        (assert (not (seteq (difference a b) (difference b a))))
        (check-sat)
    "#,
        120_000,
    );
    let status = last_status(&output);
    assert!(
        status == "sat",
        "the row-closure completion closes this goal (z3: sat); got {status}"
    );
}

/// The `set19` corpus goal, verbatim shape: `subset a d` plus
/// `not (subset (difference b a) (difference b d))` over the same ten
/// axioms.  z3 4.16.0 TIMES OUT on this goal; nixie answers `sat`
/// (~2 min) — a strict improvement over the reference, pinned so the
/// mechanism that closes it (the fresh-row mint plus the
/// structure-membership drop) cannot silently regress to `unknown`.

fn set19_family_answers_sat() {
    let output = run_bounded(
        r#"
        (set-logic UF)
        (declare-sort Set 0)
        (declare-sort Elem 0)
        (declare-fun member (Elem Set) Bool)
        (declare-fun subset (Set Set) Bool)
        (assert (forall ((?x Elem) (?s1 Set) (?s2 Set)) (=> (and (member ?x ?s1) (subset ?s1 ?s2)) (member ?x ?s2))))
        (assert (forall ((?s1 Set) (?s2 Set)) (=> (not (subset ?s1 ?s2)) (exists ((?x Elem)) (and (member ?x ?s1) (not (member ?x ?s2)))))))
        (assert (forall ((?s1 Set) (?s2 Set)) (=> (forall ((?x Elem)) (=> (member ?x ?s1) (member ?x ?s2))) (subset ?s1 ?s2))))
        (declare-fun seteq (Set Set) Bool)
        (assert (forall ((?s1 Set) (?s2 Set)) (= (seteq ?s1 ?s2) (= ?s1 ?s2))))
        (assert (forall ((?s1 Set) (?s2 Set)) (= (seteq ?s1 ?s2) (and (subset ?s1 ?s2) (subset ?s2 ?s1)))))
        (declare-fun union (Set Set) Set)
        (assert (forall ((?x Elem) (?s1 Set) (?s2 Set)) (= (member ?x (union ?s1 ?s2)) (or (member ?x ?s1) (member ?x ?s2)))))
        (declare-fun intersection (Set Set) Set)
        (assert (forall ((?x Elem) (?s1 Set) (?s2 Set)) (= (member ?x (intersection ?s1 ?s2)) (and (member ?x ?s1) (member ?x ?s2)))))
        (declare-fun difference (Set Set) Set)
        (assert (forall ((?x Elem) (?s1 Set) (?s2 Set)) (= (member ?x (difference ?s1 ?s2)) (and (member ?x ?s1) (not (member ?x ?s2))))))
        (declare-fun a () Set)
        (declare-fun b () Set)
        (declare-fun d () Set)
        (assert (subset a d))
        (assert (not (subset (difference b a) (difference b d))))
        (check-sat)
    "#,
        600_000,
    );
    let status = last_status(&output);
    assert!(
        status == "sat",
        "nixie closes this goal where z3 4.16.0 times out; got {status}"
    );
}

/// The universe-distinctness fold's groundness guard: the completed
/// model's universes contain bound-variable artifact terms (entry args
/// harvested by `collect_universes_from_model`), and folding
/// `(= ?s1 ?s2)` to `false` for symbolic operands fabricates a
/// pointwise-constant body the completion does not justify — on
/// `(or (not (= s1 s2)) (not (seteq s1 s2)))`-shaped bodies it would
/// certify satisfaction of an axiom that fails at every diagonal
/// (`seteq(z,z) = (z=z) = true`, so the disjunct is false there).  z3
/// refutes this goal; the fold must never turn it into `sat`.

fn distinct_over_composite_finite_datatype_exact_fit_is_sat() {
    // Exactly |Pair| = 6 arguments: no short-circuit may fire, and the
    // datatype theory itself must accept the enumeration.
    check(
        "(declare-datatypes ((E2 0)) (((e1) (e2))))\n\
         (declare-datatypes ((E3 0)) (((f1) (f2) (f3))))\n\
         (declare-datatypes ((Pair 0)) (((mk (a E2) (b E3)))))\n\
         (declare-const p1 Pair)(declare-const p2 Pair)(declare-const p3 Pair)\n\
         (declare-const p4 Pair)(declare-const p5 Pair)(declare-const p6 Pair)\n\
         (assert (distinct p1 p2 p3 p4 p5 p6))\n(check-sat)\n",
        "sat",
    );
}

fn distinct_over_mutually_recursive_datatypes_is_never_shortcircuited() {
    // A ⇄ B mutual recursion: infinite carriers, no short-circuit.
    check(
        "(declare-datatypes ((A 0) (B 0)) (((a1) (mkA (b B))) ((b1) (mkB (a A)))))\n\
         (declare-const x1 A)(declare-const x2 A)(declare-const x3 A)\n\
         (assert (distinct x1 x2 x3))\n(check-sat)\n",
        "sat",
    );
}

fn symbolic_argument_solves_for_the_variable() {
    // Structural unfolding alone never decides this: whatever depth it reaches,
    // the solver can satisfy `sum(k) = 6` by giving the *boundary* application
    // whatever value the arithmetic needs, for any `k`. Reaching `sat` here
    // depends on the refinement loop — the certifier computes `sum` at the
    // rejected model's `k`, and those concrete instances rule that `k` out.
    let script = format!(
        "{SUM}(declare-const k Int)\
         (assert (and (>= k 0) (= (sum k) 6)))\
         (check-sat)(get-value (k))"
    );
    let out = run(&script);
    assert_eq!(out[0], "sat", "a certified model must be found");
    assert!(
        out[1].contains('3'),
        "the only non-negative solution of sum(k) = 6 is k = 3, got {}",
        out[1]
    );
}

fn interposed_check_must_not_lose_a_kept_instantiation() {
    let script = r#"
        (set-logic UFLIA)
        (declare-fun f (Int) Int)
        (declare-const k Int)
        (assert (forall ((i Int)) (=> (and (>= i 0) (<= i 3)) (= (f i) 0))))
        (assert (or (= k 1) (= k 2)))
        (check-sat)
        (assert (= (f 1) 9))
        (assert (= k 1))
        (check-sat)
    "#;
    assert_eq!(
        verdicts(script),
        vec!["sat", "unsat"],
        "the universal forces f(1) = 0, contradicting f(1) = 9"
    );
}

/// Monotonicity across a rebase in the *unsat* direction: once a set is
/// refuted, adding assertions keeps it refuted.  A rebase that resurrected a
/// satisfying assignment from stale state would answer `sat` for the second.

fn each_mbqi_round_costs_no_more_clauses_than_the_first() {
    // Measured on this benchmark: two boundaries in the first check.
    const EXPECTED_BOUNDARIES: usize = 2;

    let mut ctx = Context::new();
    ctx.execute_script(MULTI_ROUND_BENCHMARK)
        .expect("benchmark should parse and run");
    let out = ctx
        .execute_script("(check-sat)")
        .expect("check-sat should run");
    assert!(
        out.iter().any(|line| line == "sat"),
        "the multi-round benchmark is satisfiable, got {out:?}"
    );

    let samples = ctx.solver().mbqi_round_clauses.clone();
    assert_eq!(
        samples.len(),
        EXPECTED_BOUNDARIES,
        "this benchmark's whole purpose is to cross more than one round \
         boundary; sampled clause counts were {samples:?}"
    );

    // Clause counts at: round 1's boundary, round 2's boundary, and the end of
    // the search.  The increments between them are what each round cost.
    let mut marks = samples.clone();
    marks.push(ctx.solver().sat.num_clauses());
    let increments: Vec<usize> = core::iter::once(marks[0])
        .chain(marks.windows(2).map(|w| w[1] - w[0]))
        .collect();

    let first = increments[0];
    assert!(
        increments.iter().all(|&inc| inc <= first),
        "no MBQI round may cost more clauses than the first: an increment that \
         grows with the round index is the signature of re-encoding the kept \
         lemmas instead of replaying them; increments were {increments:?} over \
         marks {marks:?}"
    );
}

fn test_dt_differential_against_brute_force_oracle() {
    let lits = literals();
    let mut selections: Vec<Vec<usize>> = Vec::new();
    for i in 0..lits.len() {
        selections.push(vec![i]);
        for j in (i + 1)..lits.len() {
            selections.push(vec![i, j]);
            for k in (j + 1)..lits.len() {
                selections.push(vec![i, j, k]);
            }
        }
    }

    let mut mismatches: Vec<String> = Vec::new();
    for selection in &selections {
        let asserts: String = selection
            .iter()
            .map(|&index| format!("(assert {}) ", lits[index].0))
            .collect();
        let script = format!(
            "(set-logic ALL)
             (declare-datatype Col ((red) (green) (blue)))
             (declare-datatype Box ((empty) (full (item Col))))
             (declare-const b1 Box)
             (declare-const b2 Box)
             {asserts}
             (check-sat)"
        );
        let actual = run_last(&script);
        let expected = oracle(selection, &lits);
        if actual != expected {
            mismatches.push(format!("{asserts}=> nixie {actual}, oracle {expected}"));
        }
    }

    assert!(
        mismatches.is_empty(),
        "{} of {} datatype formulas disagree with the brute-force oracle:\n{}",
        mismatches.len(),
        selections.len(),
        mismatches.join("\n")
    );
}
